import {beforeEach as beforePeerDiagnostic,afterEach as afterPeerDiagnostic} from 'node:test';
import {openSync as openPeerProgress,readSync as readPeerProgress,closeSync as closePeerProgress,readdirSync as listPeerProgress} from 'node:fs';
const peerProgressCases=['SUCCESS','PID','SOURCE','SOURCE_ARRAY','DUPLICATE','STDERR','EXTRA','FOREIGN_FACTORY','JOURNAL_THROW','START_EXPIRY','NODE_BINDING_MISSING','LATE_STDERR','LATE_STDOUT_EOF','LATE_STDERR_EOF'];
const peerProgressPhases=new Set(['GROUP_BEGIN','GROUP_DONE','SOURCE_BASE_BEGIN','SOURCE_BASE_DONE',...peerProgressCases.flatMap(name=>['BEGIN','KERNEL_DONE','SOURCE_DONE','NODE_DONE','CONFIGURATION_DONE','JOURNAL_DONE','FALLBACK_DONE','PEER_DONE','END'].map(edge=>'CASE_'+name+'_'+edge))]);
function readClosedPeerProgress(path){let fd;try{fd=openPeerProgress(path,'r');const bytes=Buffer.alloc(8193);let total=0;while(total<bytes.length){const count=readPeerProgress(fd,bytes,total,bytes.length-total,null);if(count===0)break;total+=count;}if(total>8192)return ['PROGRESS_REJECTED'];const rows=bytes.subarray(0,total).toString('utf8').split('\n').filter(Boolean);if(rows.length>64)return ['PROGRESS_REJECTED'];let last=-1;for(const row of rows){const match=/^([A-Z_]+):([0-9]{1,5})$/.exec(row);if(!match||!peerProgressPhases.has(match[1]))return ['PROGRESS_REJECTED'];const elapsed=Number(match[2]);if(elapsed>15000||elapsed<last)return ['PROGRESS_REJECTED'];last=elapsed;}return rows.length?rows:['PROGRESS_EMPTY'];}catch{return ['PROGRESS_UNAVAILABLE'];}finally{if(fd!==undefined)try{closePeerProgress(fd);}catch{}}}
const peerProgressDirectories=new Map();
beforePeerDiagnostic(t=>{const directory=mkdtempSync(join(tmpdir(),'goriq-public-peer-progress-'));peerProgressDirectories.set(t.name,{directory,previous:process.env.GORIQ_PUBLIC_PEER_PROGRESS_DIRECTORY});process.env.GORIQ_PUBLIC_PEER_PROGRESS_DIRECTORY=directory;});
afterPeerDiagnostic(t=>{const owned=peerProgressDirectories.get(t.name);if(!owned)return;try{const files=listPeerProgress(owned.directory);const allowed=new Set(['OWNED_0.txt','OWNED_1.txt','OWNED_2.txt','CLOSED_0.txt','CLOSED_1.txt','PLATFORM_0.txt']);const data=files.length>6||files.some(name=>!allowed.has(name))?[{group:'REJECTED',rows:['PROGRESS_REJECTED']}]:files.sort().map(name=>({group:name.slice(0,-4),rows:readClosedPeerProgress(join(owned.directory,name))}));if(data.length)console.log('GORIQ_PUBLIC_PEER_PROGRESS '+JSON.stringify(data));}finally{if(owned.previous===undefined)delete process.env.GORIQ_PUBLIC_PEER_PROGRESS_DIRECTORY;else process.env.GORIQ_PUBLIC_PEER_PROGRESS_DIRECTORY=owned.previous;peerProgressDirectories.delete(t.name);rmSync(owned.directory,{recursive:true,force:true});}});
