test('public peer fixture accepts plain and exactly one BOM while rejecting a second BOM or malformed HELLO',()=>{
 const source=readFileSync('tests/owner-code-cutover-peer.fixture.ps1','utf8');
 const programs=[...source.matchAll(/ \$js=@'\r?\n([\s\S]*?)\r?\n'@/g)];assert.equal(programs.length,1);
 const frame=JSON.stringify(hello());const outcomes=[];
 for(const [name,input] of [['PLAIN',frame],['ONE_BOM','\uFEFF'+frame],['DOUBLE_BOM','\uFEFF\uFEFF'+frame],['MALFORMED',frame+'X']]){
  const result=spawnSync(process.execPath,['--input-type=module','--eval',programs[0][1]],{input:input+'\n',encoding:'utf8',timeout:3000,maxBuffer:8192});assert.equal(result.error,undefined);
  const replied=result.status===0&&result.stderr===''&&result.stdout.endsWith('\n');outcomes.push({frameClass:name,accepted:replied});
  if(replied){const reply=JSON.parse(result.stdout);assert.equal(reply.kind,'GORIQ_OWNED_NODE_PEER_OS_DATA');assert.equal(reply.ancestry.effectCapability,false);}else assert.equal(result.stdout,'');
 }
 console.log('GORIQ_PUBLIC_EXACT_FAKE_PARSER '+JSON.stringify({outcomes,nativeAuthority:false,actualOwnerTaskAccountDpapiCalls:0}));assert.deepEqual(outcomes,[{frameClass:'PLAIN',accepted:true},{frameClass:'ONE_BOM',accepted:true},{frameClass:'DOUBLE_BOM',accepted:false},{frameClass:'MALFORMED',accepted:false}]);
});

// Validate every emitted field before exposing even a failed public control.
function validateClosedPreambleDiagnostic(value){
 const top=['profile','rows','standardInputEncodingAvailable','windows','psMajor','nativeAuthority','actualOwnerTaskAccountDpapiCalls'];assert.ok(value&&typeof value==='object'&&!Array.isArray(value));assert.equal(Object.keys(value).length,top.length);for(const key of top)assert.ok(Object.hasOwn(value,key));assert.ok(value.profile==='goriq-public-stdin-preamble-diagnostic-v1');assert.ok(value.nativeAuthority===false);assert.ok(value.actualOwnerTaskAccountDpapiCalls===0);assert.equal(typeof value.standardInputEncodingAvailable,'boolean');assert.equal(typeof value.windows,'boolean');assert.ok(Number.isSafeInteger(value.psMajor)&&value.psMajor>=1&&value.psMajor<=99);assert.ok(Array.isArray(value.rows)&&value.rows.length>=1&&value.rows.length<=3);
 const enums={mode:['DEFAULT','UTF8_BOM','UTF8_NO_BOM'],status:['PASS','FAIL','NOT_RUN'],reason:['STANDARD_INPUT_ENCODING_UNAVAILABLE'],failurePhase:['NONE','CONFIGURE','START_ENTER','STDIN_ACQUIRE','WRITE_ENTER','FLUSH_ACK_ENTER','EOF_CLOSE_ENTER'],exceptionClass:['NONE','RUNTIME','SET_VALUE','METHOD_INVOCATION','OTHER'],cleanupState:['CLOSED','NOT_STARTED','UNCONFIRMED'],firstFrameClass:['PLAIN','ONE_BOM','DOUBLE_BOM','INVALID']};const booleans=['actualExecuted','childClosed','beforeEof'],numeric=['actualExceptionHResult','managedEncodingPreambleLength'];
 for(const row of value.rows){assert.ok(row&&typeof row==='object'&&!Array.isArray(row));for(const key of ['mode','status','actualExecuted'])assert.ok(Object.hasOwn(row,key));for(const [key,item] of Object.entries(row)){if(Object.hasOwn(enums,key))assert.ok(enums[key].includes(item));else if(booleans.includes(key))assert.equal(typeof item,'boolean');else if(key==='actualExceptionHResult')assert.ok(item===null||(Number.isInteger(item)&&item>=-2147483648&&item<=2147483647));else if(key==='managedEncodingPreambleLength')assert.ok(item===0||item===3);else assert.fail('PUBLIC_PREAMBLE_CLOSED_FIELD_REJECTED');}assert.ok(Object.keys(row).every(key=>Object.hasOwn(enums,key)||booleans.includes(key)||numeric.includes(key)));if(row.status==='FAIL')for(const key of ['failurePhase','exceptionClass','actualExceptionHResult','cleanupState'])assert.ok(Object.hasOwn(row,key));}
 return value;
}

test('public owned managed stdin classifies default and explicit UTF8 preambles without disclosing frames',()=>{
 const shell=process.platform==='win32'?join(process.env.SystemRoot,'System32/WindowsPowerShell/v1.0/powershell.exe'):'pwsh';
 const child=spawnSync(shell,['-NoLogo','-NoProfile','-NonInteractive','-File','tests/owner-code-cutover-peer.fixture.ps1','-Root',process.cwd(),'-HelloPreambleDiagnostic','-NodeExecutable',process.execPath],{encoding:'utf8',timeout:15000,maxBuffer:8192});
 assert.equal(child.error,undefined);assert.equal(child.status,0,child.stdout+child.stderr);assert.equal(child.stderr,'');const value=validateClosedPreambleDiagnostic(JSON.parse(child.stdout));console.log('GORIQ_PUBLIC_STDIN_PREAMBLE '+JSON.stringify(value));
 assert.equal(value.profile,'goriq-public-stdin-preamble-diagnostic-v1');assert.equal(value.nativeAuthority,false);assert.equal(value.actualOwnerTaskAccountDpapiCalls,0);
 assert.deepEqual(value.rows.map(row=>row.mode),['DEFAULT','UTF8_BOM','UTF8_NO_BOM']);assert.equal(typeof value.standardInputEncodingAvailable,'boolean');
 for(const row of value.rows){if(row.mode==='DEFAULT'||value.standardInputEncodingAvailable){assert.equal(row.status,'PASS',JSON.stringify(row));assert.ok(['PLAIN','ONE_BOM'].includes(row.firstFrameClass));assert.equal(row.childClosed,true);assert.equal(row.beforeEof,true);assert.equal(row.cleanupState,'CLOSED');assert.ok([0,3].includes(row.managedEncodingPreambleLength));}else{assert.equal(row.status,'NOT_RUN');assert.equal(row.reason,'STANDARD_INPUT_ENCODING_UNAVAILABLE');assert.equal(row.actualExecuted,false);}}
 if(value.standardInputEncodingAvailable){assert.equal(value.rows[1].firstFrameClass,'ONE_BOM');assert.equal(value.rows[1].managedEncodingPreambleLength,3);assert.equal(value.rows[2].firstFrameClass,'PLAIN');assert.equal(value.rows[2].managedEncodingPreambleLength,0);}
});

